private fun isValidVersionCheck(expr: UExpression?, minApi: Int): Boolean {
    if (expr == null) return false
    if (expr is UBinaryExpression) {
        val op = expr.operator
        if (op == UastBinaryOperator.LOGICAL_AND) {
            return isValidVersionCheck(expr.leftOperand, minApi) || isValidVersionCheck(expr.rightOperand, minApi)
        }
        if (op == UastBinaryOperator.GREATER_OR_EQUALS || op == UastBinaryOperator.GREATER) {
            return isSdkIntAtLeast(expr.leftOperand, expr.rightOperand, minApi, allowEqual = op != UastBinaryOperator.GREATER)
        }
        if (op == UastBinaryOperator.EQUALS) {
            return isSdkIntAtLeast(expr.leftOperand, expr.rightOperand, minApi, allowEqual = true)
        }
    }
    return false
}

private fun isSdkIntAtLeast(left: UExpression?, right: UExpression?, minApi: Int, allowEqual: Boolean): Boolean {
    if (isSdkIntReference(left)) {
        val level = getApiLevel(right)
        if (level != null) {
            return if (allowEqual) level >= minApi else level > minApi
        }
    } else if (isSdkIntReference(right)) {
        val level = getApiLevel(left)
        if (level != null) {
            // right >= left means SDK_INT >= level
            return if (allowEqual) level >= minApi else level > minApi
        }
    }
    return false
}
